import unreal,json
actors=unreal.get_editor_subsystem(unreal.EditorActorSubsystem).get_all_level_actors(); rows=[]
for a in actors:
 if a.get_actor_label() in ['VerticalAccess_Stairs_01','VerticalAccess_Stairs_02','Gallery_F1_Floor_01','Atrium_PlayerStart_01']:
  v=a.get_actor_location(); row={'label':a.get_actor_label(),'class':a.get_class().get_name(),'location_cm':[v.x,v.y,v.z]}
  if a.get_actor_label()=='Gallery_F1_Floor_01': row['triangles']=a.get_component_by_class(unreal.DynamicMeshComponent).get_dynamic_mesh().get_triangle_count()
  rows.append(row)
world=unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
unreal.log(json.dumps({'world':world.get_path_name(),'actor_count':len(actors),'landmarks':rows}))
